// CreatePost is the resolver for the createPost field.
func (r *mutationResolver) CreatePost(ctx context.Context, input model.PostInput) (*model.Post, error) {
	u, err := r.Identity.GetUser(ctx, &identityv1.UserIdRequest{UserId: viewerID(ctx)})
	if err != nil {
		return nil, err
	}
	if !u.CampusEmailVerified && !u.IdVerified {
		return nil, forbidden("verify your campus email or student ID before posting")
	}
	req := &communityv1.CreatePostRequest{
		ActorId:  u.Id,
		CampusId: u.CampusId,
		Type:     down(input.Type),
		Title:    input.Title,
		Body:     input.Body,
		Location: str(input.Location),
	}
	if input.EventAt != nil {
		req.EventAt = input.EventAt.Unix()
	}
	if input.Image != nil {
		key, err := r.Store.Save(storage.Posts, input.Image.File)
		if err != nil {
			return nil, badInput(err.Error())
		}
		req.ImageKey = key
	}
	p, err := r.CommunitySvc.CreatePost(ctx, req)
	if err != nil {
		r.Store.Delete(req.ImageKey)
		return nil, err
	}
	return toPost(p), nil
}

