// ReviewVerification is the resolver for the reviewVerification field.
func (r *mutationResolver) ReviewVerification(ctx context.Context, id string, approve bool, reason *string) (*model.Verification, error) {
	v, err := r.Identity.ReviewVerification(ctx, &identityv1.ReviewRequest{Id: id, ReviewerId: viewerID(ctx), Approve: approve, Reason: str(reason)})
	if err != nil {
		return nil, err
	}
	// The ID card has done its job; don't keep personal documents around.
	r.Store.Delete(v.DocumentKey)
	title, body, link := "Your student ID is verified", "You can now publish a tutor or guide profile.", "/dashboard/profile"
	if !approve {
		title, body, link = "We couldn't verify your student ID", "Reason: "+str(reason)+". Upload a clearer photo to try again.", "/verify"
	}
	_, _ = r.Market.Notify(ctx, &marketplacev1.NotifyRequest{UserId: v.UserId, Type: "verification", Title: title, Body: body, Link: link})
	return toVerification(v), nil
}

