// SetUserStatus is the resolver for the setUserStatus field.
func (r *mutationResolver) SetUserStatus(ctx context.Context, userID string, status model.UserStatus) (*model.User, error) {
	if userID == viewerID(ctx) {
		return nil, badInput("you can't change your own status")
	}
	u, err := r.Identity.SetUserStatus(ctx, &identityv1.SetUserStatusRequest{UserId: userID, Status: down(status)})
	if err != nil {
		return nil, err
	}
	// A suspended person must disappear from search too.
	if status == model.UserStatusSuspended {
		if profiles, err := r.Market.ListUserProviderProfiles(ctx, &marketplacev1.UserRequest{UserId: userID}); err == nil {
			for _, p := range profiles.Profiles {
				if p.Status == "active" {
					_, _ = r.Market.SetProviderStatus(ctx, &marketplacev1.SetProviderStatusRequest{Id: p.Id, ActorIsAdmin: true, Status: "paused"})
				}
			}
		}
	}
	return toUser(u), nil
}

