// Providers is the resolver for the providers field.
func (r *queryResolver) Providers(ctx context.Context, filter model.ProviderFilter, page *int, pageSize *int) (*model.ProviderPage, error) {
	req := &marketplacev1.SearchProvidersRequest{
		Kind:      down(filter.Kind),
		CampusId:  str(filter.CampusID),
		SubjectId: str(filter.SubjectID),
		Query:     str(filter.Query),
		Page:      int32(intOr(page, 1)),
		PageSize:  int32(intOr(pageSize, 12)),
		ViewerId:  viewerID(ctx),
	}
	if filter.Mode != nil {
		req.Mode = down(*filter.Mode)
	}
	if filter.Service != nil {
		req.Service = down(*filter.Service)
	}
	if filter.InterviewType != nil {
		req.Service = down(*filter.InterviewType)
	}
	req.Company = str(filter.Company)
	req.ResumeReviews = filter.ResumeReviews != nil && *filter.ResumeReviews
	if filter.MinRating != nil {
		req.MinRating = *filter.MinRating
	}
	if filter.MaxRateMinor != nil {
		req.MaxRateMinor = int64(*filter.MaxRateMinor)
	}
	if filter.Sort != nil {
		req.Sort = down(*filter.Sort)
	}
	return r.searchProviders(ctx, req)
}

