// AdminStats is the resolver for the adminStats field.
func (r *queryResolver) AdminStats(ctx context.Context) (*model.AdminStats, error) {
	id, err := r.Identity.Stats(ctx, &identityv1.Empty{})
	if err != nil {
		return nil, err
	}
	mk, err := r.Market.Stats(ctx, &marketplacev1.Empty{})
	if err != nil {
		return nil, err
	}
	cm, err := r.CommunitySvc.Stats(ctx, &communityv1.Empty{})
	if err != nil {
		return nil, err
	}
	out := &model.AdminStats{
		Users: int(id.Users), EmailVerified: int(id.EmailVerified), CampusVerified: int(id.CampusVerified),
		PendingVerifications: int(id.PendingVerifications), Campuses: int(id.Campuses), PendingCampuses: int(id.PendingCampuses),
		SignupsLast7d: int(id.SignupsLast_7D),
		ActiveTutors:  int(mk.ActiveTutors), ActiveGuides: int(mk.ActiveGuides), ActiveMentors: int(mk.ActiveMentors),
		ResumeReviewsDelivered: int(mk.ResumeReviewsDelivered), DraftProfiles: int(mk.DraftProfiles),
		BookingsTotal: int(mk.BookingsTotal), BookingsRequested: int(mk.BookingsRequested), BookingsAccepted: int(mk.BookingsAccepted),
		BookingsCompleted: int(mk.BookingsCompleted), BookingsLast7d: int(mk.BookingsLast_7D), AcceptRate: mk.AcceptRate,
		CompletionRate: mk.CompletionRate, AverageRating: mk.AverageRating, Reviews: int(mk.Reviews),
		PublishedPosts: int(cm.PublishedPosts), PendingPosts: int(cm.PendingPosts), OpenReports: int(cm.OpenReports), Inquiries: int(cm.Inquiries),
	}
	for _, d := range mk.TopSubjects {
		out.TopSubjects = append(out.TopSubjects, &model.SubjectDemand{Name: d.Name, Bookings: int(d.Bookings), Tutors: int(d.Tutors)})
	}
	if out.TopSubjects == nil {
		out.TopSubjects = []*model.SubjectDemand{}
	}
	return out, nil
}

