// ProviderProfiles is the resolver for the providerProfiles field.
func (r *userResolver) ProviderProfiles(ctx context.Context, obj *model.User) ([]*model.Provider, error) {
	res, err := r.Market.ListUserProviderProfiles(ctx, &marketplacev1.UserRequest{UserId: obj.ID})
	if err != nil {
		return nil, err
	}
	out := []*model.Provider{}
	for _, p := range res.Profiles {
		if p.Status == "active" || obj.ID == viewerID(ctx) || isAdmin(ctx) {
			out = append(out, toProvider(p))
		}
	}
	return out, nil
}

